package com.example.arfas

/** Verbatim excerpts from the supplied ASHA KB, not generated quotations. */
object ArogyaSources {
 val all = listOf(
  ArogyaSource("prepare", "ASHA Job Aid: Home Visits for Newborn and Young Child (HBNC & HBYC)", "KB page 4, chunk 4599", "This will also serve as the basis for your incentive payment. Also record visits in the MCP card. ; ; HBNC Kit: This has (1) digital watch (2) digital thermometer (3) weighing scale & sling (4) baby blanket (5) spoon (6) medicines & consumables Check functionality of equipment. ; ; ASHA Drug Kit: This has the medicines & supplies (such as ORS packet, IFA syrup) that you will distribute to family of young children. ; ; MCP Card: Carry at least one MCP card to help you explain the key messages (in case mother cannot find the child’s MCP card).", "https://www.nhm.gov.in/New-Update-2022-24/CH-Programmes/HBNC-%26-HBYC-Resource-%20Material/HBNC_%26_HBYC_Jobaid_for_ASHA.pdf"),
  ArogyaSource("danger", "ASHA Job Aid: Home Visits for Newborn and Young Child (HBNC & HBYC)", "KB page 9, chunk 4603", "Counsel the family about danger signs in the baby .   Not able to feed   Weak cry or limp   Breathing is fast or difficult   Feels hot or cold to touch   Yellowness of palms and soles", "https://www.nhm.gov.in/New-Update-2022-24/CH-Programmes/HBNC-%26-HBYC-Resource-%20Material/HBNC_%26_HBYC_Jobaid_for_ASHA.pdf"),
  ArogyaSource("mother", "ASHA Job Aid: Home Visits for Newborn and Young Child (HBNC & HBYC)", "KB page 8, chunk 4602", "Ask the mother Look in mother for   Excessive bleeding, high temperature or foul smelling discharge.   Cracked nipples/painful or engorged breasts.", "https://www.nhm.gov.in/New-Update-2022-24/CH-Programmes/HBNC-%26-HBYC-Resource-%20Material/HBNC_%26_HBYC_Jobaid_for_ASHA.pdf"),
  ArogyaSource("feeding", "Postpartum Care and Home Visits for Normal Babies (ASHA)", "KB page 1, chunk 3030", "During your visits, advise the mother on the need for adequate rest and nutrition. Make sure the newborn is being kept warm and breastfed exclusively. Also look for early signs of sepsis or other illnesses in the baby and post delivery complications in the mother.", "https://www.nhsrcindia.org/sites/default/files/2021-05/Post%20Partum%20Care%20Home%20Visits%20For%20Normal%20Babies%20English.pdf"),
  ArogyaSource("measure", "ASHA Job Aid: Home Visits for Newborn and Young Child (HBNC & HBYC)", "KB page 8, chunk 4602", "Measure and record weight in checklist Measure and record temperature of newborn Check MCP card for birth dose of vaccines (given or not)", "https://www.nhm.gov.in/New-Update-2022-24/CH-Programmes/HBNC-%26-HBYC-Resource-%20Material/HBNC_%26_HBYC_Jobaid_for_ASHA.pdf"),
  ArogyaSource("record", "ASHA Job Aid: Home Visits for Newborn and Young Child (HBNC & HBYC)", "KB page 8, chunk 4601", "During the visit, record observations in MCP card. Fill the information on home visit forms.", "https://www.nhm.gov.in/New-Update-2022-24/CH-Programmes/HBNC-%26-HBYC-Resource-%20Material/HBNC_%26_HBYC_Jobaid_for_ASHA.pdf"),
  ArogyaSource("child_feeding", "ASHA Job Aid: Home Visits for Newborn and Young Child (HBNC & HBYC)", "KB page 11, chunk 4604", "Exclusive breastfeeding means giving baby only breast milk, and no other liquids or solids, not even water upto 6 months of life. Medicine drops or syrup can be given, when prescribed by a service provider.   Explain that all mothers produce enough breast milk for one or even two children up to 6 months of age. Build her confidence and support her to breastfeed.  ", "https://www.nhm.gov.in/New-Update-2022-24/CH-Programmes/HBNC-%26-HBYC-Resource-%20Material/HBNC_%26_HBYC_Jobaid_for_ASHA.pdf"),
  ArogyaSource("child_danger", "ASHA Job Aid: Home Visits for Newborn and Young Child (HBNC & HBYC)", "KB page 26, chunk 4619", "The child should be immediately taken to the health centre if the child:   Is not able to drink or breastfeed   Vomits everything or   Has convulsions/fits or   Is lethargic (less movements, difficult to wake/very sleepy) or unconscious   Has high fever   Has blood in stools   Has fast and difficult breathing", "https://www.nhm.gov.in/New-Update-2022-24/CH-Programmes/HBNC-%26-HBYC-Resource-%20Material/HBNC_%26_HBYC_Jobaid_for_ASHA.pdf"),
  ArogyaSource("safety", "ASHA Job Aid: Home Visits for Newborn and Young Child (HBNC & HBYC)", "KB page 28, chunk 4620", "At visits starting from 3rd month, discuss with parents how to protect children from injuries & accidents. Advise parents to:   Keep dangerous substances like medicines, poisons, insecticides, bleach, acids and liquid fertilizers and fuels (kerosene) out of children’s reach. Store carefully in clearly marked containers.   Keep children away from fires, cooking stoves, hot liquids and foods, and exposed electric wires to prevent burn injury.   Never leave young children alone in or near water as they can drown in a very small amount of water, even in a tub/bucket.   Do not let young children play on or near the road; always have someone older supervise them.   Secure stairs, roofs and windows using barriers in order to protect children from falling.   Keep sharp objects like knives, scissors, out of reach of children.   Keep small objects, such as coins, nuts and buttons out of reach as young children like to put them in their mouth.", "https://www.nhm.gov.in/New-Update-2022-24/CH-Programmes/HBNC-%26-HBYC-Resource-%20Material/HBNC_%26_HBYC_Jobaid_for_ASHA.pdf"),
  ArogyaSource("schedule", "ASHA Job Aid: Home Visits for Newborn and Young Child (HBNC & HBYC)", "KB page 3, chunk 4598", "3 months, 6 months, 9 months, 12 months and 15 months of age", "https://www.nhm.gov.in/New-Update-2022-24/CH-Programmes/HBNC-%26-HBYC-Resource-%20Material/HBNC_%26_HBYC_Jobaid_for_ASHA.pdf"),
  ArogyaSource("feeding_6_9","Integrated ASHA Module Part B (official PDF reviewed 2026-10-29)","PDF page 74; printed page 64; table row Between 6 to 9 months","Between 6 to 9 months\n2-3 tablespoons to be gradually increased to half (1/2) cup/katori at each meal of mashed food, 2-3 times each day and 1-2 snacks.\n2 to 3 meals each day. Offer 1 or 2 additional nutritious snacks each day in between","https://www.nhsrcindia.org/sites/default/files/2026-10/Integrated%20ASHA%20Module%20Part%20B.pdf"),
  ArogyaSource("feeding_9_12","Integrated ASHA Module Part B (official PDF reviewed 2026-10-29)","PDF page 74; printed page 64; table row Between 9 to 12 months","Between 9 to 12 months\nAtleast half (1/2) cup/katori at each meal of finely chopped or mashed food and foods that the baby can pick up with her/his fingers,\n3-4 times each day and 1-2 snacks. (5 times per day if not breastfed)","https://www.nhsrcindia.org/sites/default/files/2026-10/Integrated%20ASHA%20Module%20Part%20B.pdf"),
  ArogyaSource("feeding_12_24","Integrated ASHA Module Part B (official PDF reviewed 2026-10-29)","PDF page 74; printed page 64; table row 12 months onwards","12 months onwards\nGive at least 3/4 cup serving at a time\nMinimum of three meals a day and offer one to two snacks.","https://www.nhsrcindia.org/sites/default/files/2026-10/Integrated%20ASHA%20Module%20Part%20B.pdf"),
  ArogyaSource("feeding_24_36","Integrated ASHA Module Part B (official PDF reviewed 2026-10-29)","PDF page 75; printed page 65","For 2 years and older children, give a variety of family foods to the child, at least 1 full cup/katori (250ml) at each meal, 3-4 meals each day with 1-2 nutritious snacks between meals.\nThe quantity mentioned may be difficult for a family to measure correctly. The size of cup/katori, serving spoon/karchi, teaspoon and tablespoon can vary in size and shape.","https://www.nhsrcindia.org/sites/default/files/2026-10/Integrated%20ASHA%20Module%20Part%20B.pdf"),
 ).associateBy { it.id }
}
